def pairs(theArray, target):
    seen = set()
    thedefPairs = []
    for singleEle in theArray:
        diff = target - singleEle
        if diff in seen:
            thedefPairs.append([singleEle, diff])
        seen.add(singleEle)
    # print(seen, thedefPairs)
